INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('burat-health-center', 'Burat Health Centre', 'Gurage Zone', 7.9968, 37.9202, 'Long-supported centre recently renovated, with solar panels installed.', 'Near Endibir, Gurage Zone', 'Supported since the early days through regular doctor and volunteer visits, medicines, diagnostic equipment, training and ongoing operational support. In recent years, we''ve helped strengthen the centre further with solar power, improved facilities and new medical equipment, including an ultrasound machine.

Burat serves four local communities, three of which have already been recognised by the government as ‘model kebeles’ for hygiene and sanitation, with the fourth preparing to follow.', 1);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('zizencho-health-center', 'Zizencho Health Centre', 'Gurage Zone', 7.957172, 38.036767, 'Built in 2008 in a village with no road; now treats more than 30,000 patients a year.', 'Highland village, Gurage Zone', 'Built in 2008 with Engera''s support in an isolated highland village that had no road, electricity, or running water.

It now treats more than 30,000 patients a year, with a pre/postnatal ward, a TB unit, a water well and solar panels.', 2);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('megenesse-health-center', 'Gura Megenasse Health Centre', 'Gurage Zone', 8.133475, 37.870347, 'One of the region''s first clinics, founded by CUAMM just over 7km from Endibir.', '7km from Endibir, Gurage Zone', 'One of the first clinics in the region, founded by CUAMM (Doctors for Africa), just over 7km from Endibir.

It includes a tuberculosis unit and traditional Toukul-style buildings, plus recently installed solar panels.', 3);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('shebraber-health-center', 'Shebraber Health Centre', 'Gurage Zone', 8.040725, 37.783832, 'Built in 2014, with a TB unit and solar power added since.', 'Gurage Zone', 'Built in 2014 with Engera''s support. Since then, we''ve helped add a tuberculosis unit and a full solar power system, giving the centre reliable, sustainable power day and night.

We''re now in the process of expanding the centre to meet the growing needs of the community.', 4);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('getche-health-center', 'Getche Health Centre', 'Gurage Zone', 8.147091, 37.970044, 'Maternity ward development, safer deliveries and nurse training.', 'Gurage Zone', 'Engera supported the development of the maternity ward, improving reception facilities for pregnant women, providing safer equipment for pregnancy and delivery, training nurses in obstetric and gynaecological care, and installing solar power to keep essential services running reliably.', 5);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('attat-hospital', 'Attat Hospital', 'Gurage Zone', 8.126, 37.883, 'The referral hospital for the region, and where staff from across the network train.', 'Attat, near Wolkite, Gurage Zone', 'Attat is the referral hospital serving the Gurage Zone and the largest facility in the network, with a catchment population of more than 135,000 people.

Nurses and midwives from the smaller health centres travel here for structured clinical training, and the most complex maternal and newborn cases are referred here.', 6);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('yewere-health-center', 'Yewere Health Centre', 'Gurage Zone', 8.2, 37.92, 'A Gurage Zone health centre serving more than 16,000 people in its catchment area.', 'Gurage Zone', 'Yewere is one of the eight facilities supported through the partnership with the Ethiopian Catholic Church, serving a catchment population of 16,000+ people.

It provides primary outpatient care, mother-and-child services and immunisation, backed by Engera''s supply of medicines and equipment and by visiting medical teams.', 7);
INSERT OR IGNORE INTO facilities (slug, name, region, lat, lon, short_description, location_note, description, sort_order) VALUES ('galeya-rogdha-clinic', 'Galiye Rugda Clinic', 'Oromia region', 8.378866, 37.721511, 'An Oromia clinic being developed into a full health centre, with a school programme alongside it.', 'Near Waliso, South West Shewa Zone', 'Engera has supported Galeya for more than a decade, helping develop a clinic in this remote village in Oromia''s South West Shewa zone.

The goal is to bring it to the same standard as the rest of the network — focused on prevention, infant immunisation and pre/post-natal care — while supporting the village school alongside it.', 8);

INSERT OR IGNORE INTO testimonials (legacy_id, quote, name, title, facility_slug, sort_order) VALUES ('eyosiyas', 'Since its official founding in 2007, Engera has worked closely with the Gurage community, including the area where my family comes from. During my visit to Zizencho, I saw how local teams, supported by Engera, have brought dependable healthcare closer to families who once faced long and difficult journeys for treatment.', 'Dr Eyosiyas Arega', 'Country Advisor', 'zizencho-health-center', 1);
INSERT OR IGNORE INTO testimonials (legacy_id, quote, name, title, facility_slug, sort_order) VALUES ('solomon', 'Before the solar system was installed, we often had to stop working for half the day because the electricity would go out. Now, with solar energy, we can work properly at any hour of the day or night.', 'Mr Solomon Shurga', 'Laboratory Assistant', NULL, 2);
INSERT OR IGNORE INTO testimonials (legacy_id, quote, name, title, facility_slug, sort_order) VALUES ('rachel', 'My name is Rachel, and I''m a clinical nurse at Burat Health Center. The Attat training made a real difference for me — especially the neonatal resuscitation skills.', 'Ms Rachel', 'Clinical Nurse', 'burat-health-center', 3);
INSERT OR IGNORE INTO testimonials (legacy_id, quote, name, title, facility_slug, sort_order) VALUES ('surabhila', 'Engera partnering with Adey Pads has made a big difference for our school girls. Now they have proper pads, and more than a thousand girls can attend school confidently and without interruption.', 'Sister Surabhila', NULL, 'burat-health-center', 4);
INSERT OR IGNORE INTO testimonials (legacy_id, quote, name, title, facility_slug, sort_order) VALUES ('addis', 'I work in the ANC, delivery, and vaccination services. Our main challenge has been the power shortage — even basic things like light were not available. Even yesterday night, a mother came to give birth and the power went off. I had to use her own torchlight to help deliver the baby. Thankfully, the baby was strong and healthy, but without electricity we cannot do our work properly, especially when it comes to mothers and children. Now, with this solar project, all of these problems will be solved.', 'Addis', 'Midwife / Mother & Child Representative', 'shebraber-health-center', 5);
